// AI Agent'lar cheat sheet. 10 konu; Python örnekli.
import type { Topic } from './types'

export const agentsGiris: { q: string; a: string }[] = [
  { q: 'AI agent (ajan) nedir?', a: 'Bir hedef verilen ve ona ulaşmak için kendi karar veren dil modeli sistemi: ne yapacağını düşünür, bir araç çağırır (arama, veritabanı, e-posta), sonucu görür, gerekirse tekrar dener, işi bitirince durur. Chatbot sorunu cevaplar; ajan işi yapar. "Şu müşterinin iadesini başlat" dediğinde siparişi bulan, kuralları kontrol eden ve iadeyi açan şey ajandır.' },
  { q: 'Chatbot ile ajan arasındaki fark somut olarak ne?', a: 'Chatbot tek adımdır: soru gelir, cevap gider. Ajan bir döngüdür: düşün, araç çağır, sonucu oku, tekrar düşün, bitti de. Chatbot "iade politikamız 14 gündür" der; ajan sipariş tarihine bakar, 14 günü geçmediğini görür, iadeyi başlatır ve müşteriye bildirir.' },
  { q: 'Araç (tool) tam olarak ne?', a: 'Ajanın çağırabildiği, senin yazdığın fonksiyon: web araması, veritabanı sorgusu, e-posta gönderme, dosya okuma, hesap yapma. Modele her aracın adını, ne işe yaradığını ve parametrelerini tanıtırsın. Model aracı kendisi çalıştırmaz; "şunu şu parametreyle çağır" der, sen çalıştırıp sonucu geri verirsin. LLM API başlığındaki araç çağırma konusu bunun temelidir.' },
  { q: 'Ajan nasıl "karar veriyor"?', a: 'Her turda modele görev, araç listesi ve şimdiye kadar olanlar gönderilir; model ya bir araç çağırmak ister ya da cevap verir. Bu karar, Temeller\'de anlattığımız "sonraki parçayı tahmin et" mekanizmasıyla alınır: eğitimde gördüğü milyonlarca örnekten "bu durumda şu araç mantıklı" örüntüsünü öğrenmiştir. Sihir yok; iyi araç açıklamaları ve iyi sistem promptu kararı iyileştirir.' },
  { q: 'Ne zaman ajan kurmalı, ne zaman kurmamalı?', a: 'Adımlar önceden belliyse (her sabah raporu özetle, e-posta at) ajan kurma; sabit bir iş akışı yaz: ucuz, hızlı, öngörülebilir. Adımlar duruma göre değişiyorsa, yani "ne yapılacağı" ancak ara sonuçlara bakınca belli oluyorsa ajan gerekir. Çoğu iş için sade bir araç döngüsü yeter; çerçeve ve çoklu ajan nadiren şarttır.' },
  { q: 'Riskleri neler?', a: 'Ajan yanlış aracı çağırabilir (silinmemesi gereken e-postayı siler), sonsuz döngüye girip bütçeyi tüketebilir, bir web sayfasına gizlenmiş talimata kanabilir (prompt injection). Bu yüzden üç kural: en az yetki (sadece gereken araçlar), adım ve token sınırı, riskli eylemlerde insan onayı. Güvenlik konusu bunları ayrıntılı işler.' },
  { q: 'MCP nedir?', a: 'Model Context Protocol: araçları standart bir "sunucu" olarak tanımlama yolu. Bir kez GitHub ya da veritabanı sunucusu yazarsın; Claude Desktop, Cursor, Claude Code ve kendi ajanın aynı sunucuya bağlanıp aynı araçları kullanır. USB standardı gibi: her cihaz için ayrı kablo yerine tek standart.' },
  { q: 'Hangi çerçeveyi kullanmalıyım?', a: 'Önce hiçbirini: SDK\'nın tool runner\'ı ile elli satırlık ajan çoğu işi çözer ve ne olduğunu görürsün. Karmaşık dallanma ve kontrol noktası gerekirse LangGraph; rol tabanlı ekip için CrewAI; kod ve dosya ajanı için Claude Agent SDK; sunucuda barındırılan ajan için Anthropic\'in Managed Agents\'ı. Çerçeve değiştirmek pahalıdır, sade başla.' },
  { q: 'Çoklu ajan ne demek, gerekli mi?', a: 'Bir ana ajanın işi parçalayıp alt ajanlara dağıtması ve sonuçları birleştirmesi. Derin araştırma ve büyük görevlerde işe yarar; ama maliyet ajan sayısıyla çarpılır ve hata ayıklamak zorlaşır. Kural: önce tek ajan ve iyi araçlar; başarı yetmezse böl.' },
  { q: 'Ajanın iyi çalışıp çalışmadığını nasıl anlarım?', a: 'Gerçekçi görevlerden bir test seti kur (20-50 görev, her birinin otomatik kontrol edilebilir başarı ölçütü olsun), ajanı çalıştır, başarı oranı, adım sayısı, maliyet ve süreyi ölç. Başarısız görevlerin adımlarını oku; genelde birkaç tekrar eden hata görürsün (yanlış araç seçimi, erken bitirme). Aynı görevi birkaç kez çalıştır; ajanlar kararsızdır.' },
  { q: 'Ön koşul ne?', a: 'LLM API başlığı (özellikle araç çağırma) ve Prompt Mühendisliği. RAG\'i bilmek iyi olur çünkü arama, ajanın en sık kullandığı araçtır. Python temel düzey yeterli.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: Temel Döngü → Araç Tasarımı → Planlama ve Bellek → Çerçeveler → Çoklu Ajan → MCP → Güvenlik → Değerlendirme → Hazır Kalıplar. İlk iki konu ile çalışan bir ajan yazarsın; Güvenlik konusunu atlamadan üretime çıkma.' },
]

